-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the scal capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick B (strip)
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- scal / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'scal' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book scal refused: scal/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'af41062e6f08b66c0d6371e850cedacb' and fields = '[{"key": "m_ratio", "tol": 0.005, "unit": "-", "label": "Endpoint mobility ratio M", "expected": 1.2}, {"key": "swf", "tol": 0.0005, "unit": "fraction", "label": "Welge front saturation Swf", "expected": 0.6372}, {"key": "fwf", "tol": 0.001, "unit": "fraction", "label": "Fractional flow at the front", "expected": 0.8682763300877854}, {"key": "qi_bt_pv", "tol": 0.001, "unit": "PV", "label": "Pore volumes injected at breakthrough", "expected": 0.33077027444818546}, {"key": "ed_bt", "tol": 0.001, "unit": "fraction", "label": "Displacement efficiency at breakthrough", "expected": 0.5088773453049006}, {"key": "bt_days_8000", "tol": 2, "unit": "days", "label": "Days to breakthrough at 8000 bwpd", "expected": 926.6051908800841}]'::jsonb then 'old'
              when md5(prompt) = '42b55b7b0bdc9deefc0598c2bf03525f' and fields = '[{"key": "m_ratio", "tol": 0.005, "unit": "-", "label": "Endpoint mobility ratio M", "expected": 1.2}, {"key": "swf", "tol": 0.0005, "unit": "fraction", "label": "Welge front saturation Swf", "expected": 0.6372}, {"key": "fwf", "tol": 0.001, "unit": "fraction", "label": "Fractional flow at the front", "expected": 0.8682763300877854}, {"key": "qi_bt_pv", "tol": 0.001, "unit": "PV", "label": "Pore volumes injected at breakthrough", "expected": 0.33077027444818546}, {"key": "ed_bt", "tol": 0.001, "unit": "fraction", "label": "Displacement efficiency at breakthrough", "expected": 0.5088773453049006}, {"key": "bt_days_8000", "tol": 2, "unit": "days", "label": "Days to breakthrough at 8000 bwpd", "expected": 926.6051908800841}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'scal' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book scal refused: scal/beginner matches neither its published form (prompt md5 af41062e6f08b66c0d6371e850cedacb) nor its W1 form (prompt md5 42b55b7b0bdc9deefc0598c2bf03525f), with the fields this file was generated against';
  end if;

  -- scal / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'scal' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book scal refused: scal/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd49ca9dc7f161bcab92750419be2ec3a' and fields = '[{"key": "lab_j_per_psi", "tol": 0.0001, "unit": "1/psi", "label": "Ahmed 4-7 lab J factor per psi", "expected": 0.0967993827459659}, {"key": "j_at_sw02", "tol": 0.0005, "unit": "-", "label": "Ahmed 4-7 J at Sw 0.20 (full precision)", "expected": 0.16939891980544033}, {"key": "res_pc_sw02", "tol": 0.002, "unit": "psi", "label": "Reservoir Pc at Sw 0.20 from the printed J", "expected": 1.5534071373580902}, {"key": "h_entry_m", "tol": 0.01, "unit": "m", "label": "Ekene entry height above the FWL", "expected": 3.142982863763458}, {"key": "fwl_m", "tol": 0.02, "unit": "m TVD", "label": "Ekene free water level", "expected": 1563.1429828637636}, {"key": "sw_at_crest", "tol": 0.0005, "unit": "fraction", "label": "Water saturation at the crest", "expected": 0.35062979402484734}]'::jsonb then 'old'
              when md5(prompt) = 'f7001c267089943d6865017da876471f' and fields = '[{"key": "lab_j_per_psi", "tol": 0.0001, "unit": "1/psi", "label": "Ahmed 4-7 lab J factor per psi", "expected": 0.0967993827459659}, {"key": "j_at_sw02", "tol": 0.0005, "unit": "-", "label": "Ahmed 4-7 J at Sw 0.20 (full precision)", "expected": 0.16939891980544033}, {"key": "res_pc_sw02", "tol": 0.002, "unit": "psi", "label": "Reservoir Pc at Sw 0.20 from the printed J", "expected": 1.5534071373580902}, {"key": "h_entry_m", "tol": 0.01, "unit": "m", "label": "Ekene entry height above the FWL", "expected": 3.142982863763458}, {"key": "fwl_m", "tol": 0.02, "unit": "m TVD", "label": "Ekene free water level", "expected": 1563.1429828637636}, {"key": "sw_at_crest", "tol": 0.0005, "unit": "fraction", "label": "Water saturation at the crest", "expected": 0.35062979402484734}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'scal' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book scal refused: scal/intermediate matches neither its published form (prompt md5 d49ca9dc7f161bcab92750419be2ec3a) nor its W1 form (prompt md5 f7001c267089943d6865017da876471f), with the fields this file was generated against';
  end if;

  -- scal / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book scal refused: scal/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '2f1bd16e772b7aab505fc5a0f04d4c6d' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb then 'old'
              when md5(prompt) = 'c8e94f82b3e55c070b52274fa9dcfc6f' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book scal refused: scal/advanced matches neither its published form (prompt md5 2f1bd16e772b7aab505fc5a0f04d4c6d) nor its W1 form (prompt md5 c8e94f82b3e55c070b52274fa9dcfc6f), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book scal: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book scal refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the Ekene displacement from its designed relative permeability set (Corey with Swc 0.35, Sor 0.25, krwMax 0.3, kroMax 0.9 and the Corey exponents the fixture itself carries; water 0.5 cp against oil 1.8 cp) and read the flood: the endpoint mobility ratio, the Welge front saturation and the fractional flow at the front, the pore volumes injected at breakthrough, the displacement efficiency at breakthrough, and the days to breakthrough at a steady 8000 bwpd on the fixture pore volume.',
           fields = '[{"key": "m_ratio", "tol": 0.005, "unit": "-", "label": "Endpoint mobility ratio M", "expected": 1.2}, {"key": "swf", "tol": 0.0005, "unit": "fraction", "label": "Welge front saturation Swf", "expected": 0.6372}, {"key": "fwf", "tol": 0.001, "unit": "fraction", "label": "Fractional flow at the front", "expected": 0.8682763300877854}, {"key": "qi_bt_pv", "tol": 0.001, "unit": "PV", "label": "Pore volumes injected at breakthrough", "expected": 0.33077027444818546}, {"key": "ed_bt", "tol": 0.001, "unit": "fraction", "label": "Displacement efficiency at breakthrough", "expected": 0.5088773453049006}, {"key": "bt_days_8000", "tol": 2, "unit": "days", "label": "Days to breakthrough at 8000 bwpd", "expected": 926.6051908800841}]'::jsonb
     where app_slug = 'scal' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book scal refused: scal/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '42b55b7b0bdc9deefc0598c2bf03525f' and fields = '[{"key": "m_ratio", "tol": 0.005, "unit": "-", "label": "Endpoint mobility ratio M", "expected": 1.2}, {"key": "swf", "tol": 0.0005, "unit": "fraction", "label": "Welge front saturation Swf", "expected": 0.6372}, {"key": "fwf", "tol": 0.001, "unit": "fraction", "label": "Fractional flow at the front", "expected": 0.8682763300877854}, {"key": "qi_bt_pv", "tol": 0.001, "unit": "PV", "label": "Pore volumes injected at breakthrough", "expected": 0.33077027444818546}, {"key": "ed_bt", "tol": 0.001, "unit": "fraction", "label": "Displacement efficiency at breakthrough", "expected": 0.5088773453049006}, {"key": "bt_days_8000", "tol": 2, "unit": "days", "label": "Days to breakthrough at 8000 bwpd", "expected": 926.6051908800841}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book scal refused: scal/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Work Ahmed Example 4-7 start to finish: the lab J-per-psi factor for the 80 md, 16 percent porosity core, the full-precision J at Sw 0.20, and the reservoir capillary pressure at Sw 0.20 obtained by scaling the PRINTED (rounded) J column back through the 120 md, 19 percent porosity reservoir rock, which is the chain the book itself uses. Then carry the Ekene plugs to the field on the sand''s own rock and fluids: the entry height in metres, the free water level in metres TVD given the mapped 1560 m contact, and the water saturation at the crest of the structure.',
           fields = '[{"key": "lab_j_per_psi", "tol": 0.0001, "unit": "1/psi", "label": "Ahmed 4-7 lab J factor per psi", "expected": 0.0967993827459659}, {"key": "j_at_sw02", "tol": 0.0005, "unit": "-", "label": "Ahmed 4-7 J at Sw 0.20 (full precision)", "expected": 0.16939891980544033}, {"key": "res_pc_sw02", "tol": 0.002, "unit": "psi", "label": "Reservoir Pc at Sw 0.20 from the printed J", "expected": 1.5534071373580902}, {"key": "h_entry_m", "tol": 0.01, "unit": "m", "label": "Ekene entry height above the FWL", "expected": 3.142982863763458}, {"key": "fwl_m", "tol": 0.02, "unit": "m TVD", "label": "Ekene free water level", "expected": 1563.1429828637636}, {"key": "sw_at_crest", "tol": 0.0005, "unit": "fraction", "label": "Water saturation at the crest", "expected": 0.35062979402484734}]'::jsonb
     where app_slug = 'scal' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book scal refused: scal/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f7001c267089943d6865017da876471f' and fields = '[{"key": "lab_j_per_psi", "tol": 0.0001, "unit": "1/psi", "label": "Ahmed 4-7 lab J factor per psi", "expected": 0.0967993827459659}, {"key": "j_at_sw02", "tol": 0.0005, "unit": "-", "label": "Ahmed 4-7 J at Sw 0.20 (full precision)", "expected": 0.16939891980544033}, {"key": "res_pc_sw02", "tol": 0.002, "unit": "psi", "label": "Reservoir Pc at Sw 0.20 from the printed J", "expected": 1.5534071373580902}, {"key": "h_entry_m", "tol": 0.01, "unit": "m", "label": "Ekene entry height above the FWL", "expected": 3.142982863763458}, {"key": "fwl_m", "tol": 0.02, "unit": "m TVD", "label": "Ekene free water level", "expected": 1563.1429828637636}, {"key": "sw_at_crest", "tol": 0.0005, "unit": "fraction", "label": "Water saturation at the crest", "expected": 0.35062979402484734}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book scal refused: scal/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Fit the 13-row lab relative permeability grid (Sw 0.35 to 0.75 in twelve equal steps, Swirr 0.25 given) as the lab sheet prints it, every kr rounded to three decimals, with fixed endpoints taken from the table and report the fitted water exponent. Average the three Ekene plug J-curves at the true Swirr 0.25 and report the refitted coefficient a, which drifts off the design 0.25 through the log-linear resampling. Then design the flood on the Ekene sand: the displacement efficiency at breakthrough for the dip case (k 250 md, cross-section 20000 ft2, total rate 2000 rb/d, water gravity 1.03, oil gravity from API 32) displacing updip at plus 10 degrees and again downdip at minus 10 degrees, the polymer screening case at a water viscosity multiplier of 4, and the height-averaged water saturation over the crest column from the composite trapezoid with 2000 intervals between the contact and the crest.',
           fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb
     where app_slug = 'scal' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book scal refused: scal/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'c8e94f82b3e55c070b52274fa9dcfc6f' and fields = '[{"key": "fitted_nw_printed_grid", "tol": 0.001, "unit": "-", "label": "Fitted water Corey exponent nw, kr printed to 3 dp", "expected": 2.4318603318221883}, {"key": "avg_refit_a", "tol": 0.0005, "unit": "-", "label": "Averaged-refit J coefficient a", "expected": 0.2491501585202375}, {"key": "gravity_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing updip at 10 degrees", "expected": 0.5095807170488317}, {"key": "downdip_ed_bt", "tol": 0.0005, "unit": "fraction", "label": "EDbt displacing downdip at 10 degrees", "expected": 0.5081700834294871}, {"key": "polymer_ed_bt", "tol": 0.001, "unit": "fraction", "label": "EDbt with the water viscosity times 4", "expected": 0.5771964898801638}, {"key": "sw_avg_crest_column", "tol": 0.002, "unit": "fraction", "label": "Height-averaged Sw over the crest column", "expected": 0.48345033394940007}]'::jsonb) from public.academy_capstones where app_slug = 'scal' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book scal refused: scal/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book scal: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
